'use client'

import { Check, X, Zap, Loader2, Sparkles } from 'lucide-react'
import { TrialOfferDialog } from '@/components/subscription/TrialOfferDialog'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import { useState, useEffect } from 'react'
import Script from 'next/script'
import { toast } from 'sonner'
import { useRouter, useSearchParams } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'

declare global {
    interface Window {
        Cashfree: any;
    }
}

export default function PricingPage() {
    const [loading, setLoading] = useState(false)
    const [currentPlan, setCurrentPlan] = useState<string>('FREE')
    const [isLoadingPlan, setIsLoadingPlan] = useState(true)
    const _router = useRouter()
    const searchParams = useSearchParams()
    // const searchParams = typeof window !== 'undefined' ? new URLSearchParams(window.location.search) : null // BROKEN: Causes infinite loop
    const [trialUsed, setTrialUsed] = useState(false)
    const [subStatus, setSubStatus] = useState<string>('')
    const [orgId, setOrgId] = useState<string>('')
    const [showTrialDialog, setShowTrialDialog] = useState(false)
    const supabase = createClient()

    // Verify Payment Effect
    useEffect(() => {
        const orderId = searchParams?.get('order_id')
        if (orderId) {
            verifyCashfreePayment(orderId)
        }
    }, [searchParams])

    const verifyCashfreePayment = async (orderId: string) => {
        setLoading(true)
        try {
            const res = await fetch('/api/cashfree/verify', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ orderId })
            })
            const data = await res.json()

            if (data.success) {
                toast.success("Payment Successful! Welcome to Pro.")
                // Clean URL
                window.history.replaceState({}, document.title, window.location.pathname)
                // Force Reload
                window.location.reload()
            } else {
                toast.error(data.error || "Payment verification failed")
            }
        } catch (error) {
            toast.error("Verification failed or Payment was cancelled")
        } finally {
            // Clean URL even on failure to prevent loop/retry on refresh
            window.history.replaceState({}, document.title, window.location.pathname)
            setLoading(false)
        }
    }

    // Load Plan Details
    useEffect(() => {
        async function fetchPlan() {
            const { data: { user } } = await supabase.auth.getUser()
            if (user) {
                const { data: profile } = await supabase
                    .from('profiles')
                    .select('organization_id, organizations(plan_type, trial_used, subscription_status)')
                    .eq('id', user.id)
                    .single()

                // @ts-ignore
                if (profile?.organizations?.plan_type) {
                    // @ts-ignore
                    setCurrentPlan(profile.organizations.plan_type)
                    // @ts-ignore
                    setTrialUsed(profile.organizations.trial_used || false)
                    // @ts-ignore
                    setSubStatus(profile.organizations.subscription_status || '')
                }
                if (profile?.organization_id) setOrgId(profile.organization_id)
            }
            setIsLoadingPlan(false)
        }
        fetchPlan()
    }, [supabase])

    // ... existing plan fetch effect ...

    const handlePayment = async () => {
        setLoading(true)
        try {
            // 1. Create Order & Get Session
            const res = await fetch('/api/cashfree/create-order', {
                method: 'POST'
            })
            const data = await res.json()

            if (data.error) {
                toast.error(data.error)
                setLoading(false)
                return
            }

            // 2. Initialize Cashfree SDK
            const cashfree = new window.Cashfree({
                mode: process.env.NEXT_PUBLIC_CASHFREE_ENV === 'PRODUCTION' ? "production" : "sandbox"
            });

            // 3. Open Checkout
            cashfree.checkout({
                paymentSessionId: data.paymentSessionId,
                returnUrl: `${window.location.origin}/pricing?order_id=${data.orderId}`
            });

        } catch (error) {
            console.error("Payment Error:", error)
            toast.error("Failed to initiate payment")
            setLoading(false)
        }
    }

    if (isLoadingPlan) {
        return <div className="flex h-full items-center justify-center"><Loader2 className="h-8 w-8 animate-spin" /></div>
    }

    return (
        <div className="flex-1 space-y-8 p-8 pt-6">
            <Script
                id="cashfree-js"
                src="https://sdk.cashfree.com/js/v3/cashfree.js"
                strategy="lazyOnload"
            />

            <div className="flex flex-col items-center justify-center text-center gap-4 mb-16">
                <h2 className="text-4xl md:text-5xl font-extrabold tracking-tight text-white">
                    Simple, Transparent Pricing
                </h2>
                <p className="text-lg text-slate-400 max-w-2xl">
                    Choose the plan that's right for your business. Upgrade anytime as you grow.
                </p>
            </div>

            <div className="grid grid-cols-1 gap-8 lg:grid-cols-3 lg:gap-10 max-w-7xl mx-auto">
                {/* Free Plan */}
                <div className={cn(
                    "relative flex flex-col rounded-3xl border border-white/5 bg-white/5 backdrop-blur-sm p-8 shadow-2xl transition-all duration-300 hover:scale-[1.02] hover:bg-white/10 hover:shadow-indigo-500/10",
                    currentPlan === 'FREE' ? "ring-1 ring-white/10" : ""
                )}>
                    <div className="mb-8">
                        <h3 className="text-xl font-medium text-slate-200">Starter</h3>
                        <p className="text-sm text-slate-400 mt-2">Perfect for small shops just starting out.</p>
                        <div className="mt-6 flex items-baseline">
                            <span className="text-4xl font-bold text-white">₹0</span>
                            <span className="ml-1 text-sm font-medium text-slate-500">/mo</span>
                        </div>
                    </div>
                    <ul className="mb-8 space-y-4 flex-1">
                        {[
                            'Single User',
                            'Basic Inventory Tracking',
                            'Basic Reports (KPIs & trends)',
                            'Sales & Invoices 🧾',
                            'Low Stock Table'
                        ].map((feature) => (
                            <li key={feature} className="flex items-center gap-3">
                                <div className="rounded-full bg-slate-800 p-1">
                                    <Check className="h-3.5 w-3.5 text-slate-400" />
                                </div>
                                <span className="text-sm text-slate-300">{feature}</span>
                            </li>
                        ))}
                        <li className="flex items-center gap-3 text-slate-500">
                            <div className="rounded-full bg-slate-800/50 p-1">
                                <X className="h-3.5 w-3.5" />
                            </div>
                            <span className="text-sm">No Financial Analytics</span>
                        </li>
                        <li className="flex items-center gap-3 text-slate-500">
                            <div className="rounded-full bg-slate-800/50 p-1">
                                <X className="h-3.5 w-3.5" />
                            </div>
                            <span className="text-sm">No Barcode Scanning</span>
                        </li>
                    </ul>
                    <Button
                        className="w-full bg-white/5 hover:bg-white/10 text-slate-300 border-0 rounded-xl transition-all duration-200"
                        disabled
                    >
                        {currentPlan === 'FREE' ? 'Current Plan' : 'Downgrade'}
                    </Button>
                </div>

                {/* Pro Plan - Highlighted */}
                <div className={cn(
                    "relative flex flex-col rounded-3xl border border-indigo-500/30 bg-indigo-900/10 backdrop-blur-md p-8 shadow-2xl transition-all duration-300 hover:scale-[1.02] hover:shadow-indigo-500/20 ring-1 ring-indigo-500/50 scale-105 z-10",
                    currentPlan === 'PRO' ? "ring-indigo-500" : ""
                )}>
                    <div className="absolute -top-4 left-0 right-0 mx-auto w-fit rounded-full bg-indigo-600 px-4 py-1 text-xs font-medium text-white shadow-lg shadow-indigo-500/40 flex items-center gap-1">
                        MOST POPULAR
                    </div>

                    <div className="mb-8">
                        <div className="flex justify-between items-start">
                            <div>
                                <h3 className="text-xl font-medium text-indigo-300 flex items-center gap-2">
                                    Pro <Zap className="h-4 w-4 text-yellow-400 fill-yellow-400" />
                                </h3>
                                <p className="text-sm text-indigo-200/60 mt-2">For growing businesses that need control.</p>
                            </div>
                            {currentPlan === 'PRO' && subStatus === 'TRIALING' && (
                                <span className="text-xs font-semibold px-2 py-0.5 rounded-full bg-orange-500/20 text-orange-400 border border-orange-500/30">
                                    Trial Active
                                </span>
                            )}
                        </div>
                        <div className="mt-6 flex items-baseline">
                            <span className="text-5xl font-bold text-white">₹399</span>
                            <span className="ml-1 text-sm font-medium text-indigo-200/60">/mo</span>
                        </div>
                    </div>

                    <ul className="mb-8 space-y-4 flex-1">
                        {[
                            { text: '5 Team Members', icon: Check },
                            { text: 'Advanced Financial Analytics 💰', icon: Check },
                            { text: 'Barcode Scanning App 📱', icon: Check },
                            { text: 'Stock Movement Logs (Audit Trail) 📋', icon: Check },
                            { text: 'Warehouse Transfers 🚚', icon: Check },
                            { text: 'Low Stock Email Alerts', icon: Check },
                            { text: 'AI Stock Predictions 🤖', icon: Check },
                            { text: 'Bulk CSV Import/Export 📤', icon: Check },
                        ].map((item) => (
                            <li key={item.text} className="flex items-center gap-3">
                                <div className="rounded-full bg-indigo-500/20 p-1">
                                    <item.icon className="h-3.5 w-3.5 text-indigo-400" />
                                </div>
                                <span className="text-sm text-white font-medium">{item.text}</span>
                            </li>
                        ))}
                    </ul>

                    <div className="flex flex-col gap-3">
                        {currentPlan === 'PRO' && subStatus !== 'TRIALING' ? (
                            <Button className="w-full bg-emerald-500/20 text-emerald-400 cursor-default hover:bg-emerald-500/20 border border-emerald-500/30 rounded-xl" disabled>
                                <Check className="mr-2 h-4 w-4" /> Current Plan
                            </Button>
                        ) : (
                            <>
                                {currentPlan === 'PRO' && subStatus === 'TRIALING' && (
                                    <div className="w-full mb-3 p-3 bg-indigo-500/10 border border-indigo-500/20 rounded-xl text-center">
                                        <p className="text-sm font-medium text-indigo-400">
                                            ⚠️ Trial Mode Active
                                        </p>
                                        <p className="text-xs text-indigo-300/80 mt-1">
                                            Upgrade now to keep your data & features forever.
                                        </p>
                                    </div>
                                )}

                                {currentPlan === 'FREE' && !trialUsed && (
                                    <Button
                                        className="w-full bg-orange-600 hover:bg-orange-700 text-white border-0 rounded-xl shadow-lg shadow-orange-500/25 transition-all duration-300 font-bold"
                                        onClick={() => {
                                            toast.info("Loading offer details...")
                                            setShowTrialDialog(true)
                                        }}
                                    >
                                        <Sparkles className="mr-2 h-4 w-4 fill-white" />
                                        Start 5-Day Free Trial
                                    </Button>
                                )}

                                <Button
                                    onClick={handlePayment}
                                    disabled={loading}
                                    className="w-full bg-indigo-600 hover:bg-indigo-700 text-white border-0 rounded-xl shadow-lg shadow-indigo-500/25 transition-all duration-300"
                                >
                                    {loading ? (
                                        <>
                                            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                            Processing...
                                        </>
                                    ) : (
                                        <>
                                            <Zap className="mr-2 h-4 w-4 fill-white" />
                                            Upgrade to Pro
                                        </>
                                    )}
                                </Button>
                            </>
                        )}
                    </div>
                </div>

                {/* Enterprise Plan */}
                <div className="relative flex flex-col rounded-3xl border border-white/5 bg-white/5 backdrop-blur-sm p-8 shadow-2xl transition-all duration-300 hover:scale-[1.02] hover:bg-white/10 hover:shadow-indigo-500/10">
                    <div className="mb-8">
                        <h3 className="text-xl font-medium text-slate-200">Enterprise</h3>
                        <p className="text-sm text-slate-400 mt-2">Custom solutions for large organizations.</p>
                        <div className="mt-6 flex items-baseline">
                            <span className="text-4xl font-bold text-white">Custom</span>
                        </div>
                    </div>
                    <ul className="mb-8 space-y-4 flex-1">
                        {[
                            'Unlimited Users & Roles',
                            'Custom Feature Development',
                            'Dedicated Account Manager',
                            'Custom Integrations (ERP/SAP)',
                            'On-premise Deployment',
                            '24/7 Priority Support'
                        ].map((feature) => (
                            <li key={feature} className="flex items-center gap-3">
                                <div className="rounded-full bg-purple-500/20 p-1">
                                    <Check className="h-3.5 w-3.5 text-purple-400" />
                                </div>
                                <span className="text-sm text-slate-300">{feature}</span>
                            </li>
                        ))}
                    </ul>
                    <Button
                        className="w-full bg-white/10 hover:bg-white/20 text-white border-0 rounded-xl transition-all duration-200"
                        asChild
                    >
                        <a href="mailto:sales@inventory.com?subject=Enterprise%20Plan%20Inquiry">Contact Sales</a>
                    </Button>
                </div>
            </div>

            {/* Trust Signals */}
            <div className="mt-12 text-center">
                <p className="text-muted-foreground text-sm">
                    Trusted by 500+ businesses worldwide.
                    <br />
                    Secure payments via Cashfree Payments. Cancel anytime.
                </p>
            </div>
            <TrialOfferDialog
                open={showTrialDialog}
                onOpenChange={setShowTrialDialog}
                organizationId={orgId}
                trialUsed={trialUsed}
                planType={currentPlan}
            />
        </div >
    )
}

'use server'

import { createClient } from '@/lib/supabase/server'
import { getWarehouseCookie } from './warehouse-cookie'
import { addDays, format, subDays, startOfDay, endOfDay } from 'date-fns'

export interface DashboardMetric {
    label: string
    value: number
    change?: number
    trend?: 'up' | 'down' | 'neutral'
}

export type ChartData = {
    date: string
    revenue: number
    orders: number
}[]

export async function getDashboardMetrics() {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return null

    // Get Org ID
    const { data: profile } = await supabase.from('profiles').select('organization_id').eq('id', user.id).single()
    const organizationId = profile?.organization_id

    if (!organizationId) return null

    const warehouseId = await getWarehouseCookie()

    // 1. Fetch Item Stats
    let itemsCount = 0
    let lowStockCount = 0
    let totalStockValue = 0

    if (warehouseId) {
        // Local Scope
         const { data: stockItems } = await supabase
            .from('item_stock')
            .select(`
                quantity,
                item:items (id, min_stock, price)
            `)
            .eq('location_id', warehouseId)
        
        if (stockItems) {
            itemsCount = stockItems.length
            // @ts-expect-error -- third-party type mismatch
            lowStockCount = stockItems.filter(i => i.quantity < (i.item?.min_stock || 0)).length
            // @ts-expect-error -- third-party type mismatch
            totalStockValue = stockItems.reduce((acc, curr) => acc + (curr.quantity * (curr.item?.price || 0)), 0)
        }

    } else {
        // Global Scope
        const { data: allItems } = await supabase
            .from('items')
            .select('current_stock, min_stock, price')
            .eq('organization_id', organizationId)
        
        if (allItems) {
            itemsCount = allItems.length
            lowStockCount = allItems.filter(i => (i.current_stock || 0) < (i.min_stock || 0)).length
             totalStockValue = allItems.reduce((acc, curr) => acc + ((curr.current_stock || 0) * (curr.price || 0)), 0)
        }
    }

    return {
        itemsCount,
        lowStockCount,
        totalStockValue,
    }
}

export async function getRevenueChartData(period: '7d' | '30d' = '7d'): Promise<ChartData> {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return []

    const { data: profile } = await supabase.from('profiles').select('organization_id').eq('id', user.id).single()
    const organizationId = profile?.organization_id
    if (!organizationId) return []

    const days = period === '30d' ? 30 : 7
    const startDate = subDays(new Date(), days)

    // Fetch invoices in range
    const { data: invoices } = await supabase
        .from('invoices')
        .select(`created_at, total_amount`)
        .eq('organization_id', organizationId)
        .gte('created_at', startDate.toISOString())
        .order('created_at', { ascending: true })
    
    // Group by day
    const groupedData = new Map<string, { revenue: number, orders: number }>()

    // Initialize all days
    for (let i = 0; i <= days; i++) {
        const d = addDays(startDate, i)
        const dateKey = format(d, 'MMM dd')
        groupedData.set(dateKey, { revenue: 0, orders: 0 })
    }

    // Populate actuals
    invoices?.forEach(inv => {
        const dateKey = format(new Date(inv.created_at), 'MMM dd')
        const current = groupedData.get(dateKey) || { revenue: 0, orders: 0 }
        groupedData.set(dateKey, {
            revenue: current.revenue + (inv.total_amount || 0),
            orders: current.orders + 1
        })
    })

    return Array.from(groupedData.entries()).map(([date, data]) => ({
        date,
        revenue: data.revenue,
        orders: data.orders
    }))
}

'use client'

import { , useTransition } from "react"
import { useRouter } from "next/navigation"
import { Loader2 } from "lucide-react"
import { toast } from "sonner"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { createClient } from "@/lib/supabase/client"

export default function UpdatePasswordPage() {
    const router = useRouter()
    const [isPending, startTransition] = useTransition()

    async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
        event.preventDefault()
        const formData = new FormData(event.currentTarget)
        const password = formData.get("password") as string
        const confirmPassword = formData.get("confirmPassword") as string

        if (password !== confirmPassword) {
            toast.error("Passwords do not match")
            return
        }

        startTransition(async () => {
            const supabase = createClient()
            const { error } = await supabase.auth.updateUser({
                password: password
            })

            if (error) {
                toast.error(error.message)
            } else {
                toast.success("Password updated successfully!")
                router.push("/dashboard")
            }
        })
    }

    return (
        <div className="container flex h-screen w-screen flex-col items-center justify-center">
            <div className="mx-auto flex w-full flex-col justify-center space-y-6 sm:w-[350px]">
                <div className="flex flex-col space-y-2 text-center">
                    <h1 className="text-2xl font-semibold tracking-tight">
                        Set New Password
                    </h1>
                    <p className="text-sm text-muted-foreground">
                        Please enter your new password below.
                    </p>
                </div>

                <form onSubmit={onSubmit}>
                    <div className="grid gap-4">
                        <div className="grid gap-2">
                            <Label htmlFor="password">New Password</Label>
                            <Input
                                id="password"
                                name="password"
                                type="password"
                                placeholder="••••••••"
                                disabled={isPending}
                                required
                                minLength={8}
                            />
                        </div>
                        <div className="grid gap-2">
                            <Label htmlFor="confirmPassword">Confirm New Password</Label>
                            <Input
                                id="confirmPassword"
                                name="confirmPassword"
                                type="password"
                                placeholder="••••••••"
                                disabled={isPending}
                                required
                                minLength={8}
                            />
                        </div>
                        <Button disabled={isPending}>
                            {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                            Update Password
                        </Button>
                    </div>
                </form>
            </div>
        </div>
    )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Plus, Loader2, ScanBarcode, ChevronsUpDown, Check } from 'lucide-react'
import { createItem } from '@/app/actions/items'
import { ITEM_CATEGORIES, ITEM_UNITS } from '@/lib/constants'
import { BarcodeScanner } from '@/components/common/BarcodeScanner'
import {
} from "@/components/ui/command"
import {
    Popover,
    PopoverContent,
    PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'

interface CreateItemDialogProps {
    open?: boolean
    onOpenChange?: (open: boolean) => void
    defaultSku?: string
    defaultName?: string
    defaultCategory?: string
    defaultUnit?: string
    defaultSize?: string
    defaultColor?: string
    hideTrigger?: boolean
}

export function CreateItemDialog({
    open: controlledOpen,
    onOpenChange: controlledOnOpenChange,
    defaultSku = '',
    defaultName = '',
    defaultCategory = '',
    defaultUnit = 'pcs',
    defaultSize = '',
    defaultColor = '',
    hideTrigger = false
}: CreateItemDialogProps = {}) {
    const [internalOpen, setInternalOpen] = useState(false)
    const isControlled = controlledOpen !== undefined

    const open = isControlled ? controlledOpen : internalOpen
    const setOpen = (newOpen: boolean) => {
        if (isControlled) {
            controlledOnOpenChange?.(newOpen)
        } else {
            setInternalOpen(newOpen)
        }
    }

    const [isScanning, setIsScanning] = useState(false)
    const [sku, setSku] = useState(defaultSku)
    const [name, setName] = useState(defaultName)
    const [category, setCategory] = useState(defaultCategory)
    const [unit, setUnit] = useState(defaultUnit)
    const [size, setSize] = useState(defaultSize)
    const [color, setColor] = useState(defaultColor)

    const [isPending, startTransition] = useTransition()
    const _router = useRouter()

    // Sync state with props when dialog opens/closes
    const [prevOpen, setPrevOpen] = useState(open)
    if (open !== prevOpen) {
        setPrevOpen(open)
        if (open) {
            // Only reset from defaults if we are opening
            setSku(defaultSku)
            setName(defaultName)
            if (defaultCategory) setCategory(defaultCategory)
            if (defaultUnit) setUnit(defaultUnit)
            if (defaultSize) setSize(defaultSize)
            if (defaultColor) setColor(defaultColor)
        }
    }

    async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
        event.preventDefault()
        const formData = new FormData(event.currentTarget)

        // Ensure state values are present if user didn't type them
        if (sku && !formData.get('sku')) formData.set('sku', sku)
        if (name && !formData.get('name')) formData.set('name', name)

        // Ensure combobox values are set
        if (category) formData.set('category', category)
        if (unit) formData.set('unit', unit)

        startTransition(async () => {
            const result = await createItem({}, formData)
            if (result?.error) {
                toast.error(result.error)
            } else {
                toast.success('Item created successfully')
                setOpen(false)
                // Reset form
                setSku('')
                setName('')
            }
        })
    }

    async function fetchProductDetails(barcode: string) {
        setSku(barcode)
        toast.info('Fetching product details...')
        try {
            const response = await fetch(`https://world.openfoodfacts.org/api/v0/product/${barcode}.json`)
            const data = await response.json()

            if (data.status === 1 && data.product) {
                const productName = data.product.product_name || data.product.product_name_en
                if (productName) {
                    setName(productName)
                    toast.success('Product found: ' + productName)
                } else {
                    toast.info('Product found but no name available')
                }
            } else {
                toast.info('Product not found in database')
            }
        } catch (error) {
            console.error('Error fetching product:', error)
            toast.error('Failed to fetch product details')
        }
    }

    return (
        <Dialog open={open} onOpenChange={setOpen}>
            {!hideTrigger && (
                <DialogTrigger asChild>
                    <Button>
                        <Plus className="mr-2 h-4 w-4" /> Add Item
                    </Button>
                </DialogTrigger>
            )}
