                </form>
            </DialogContent>
            <BarcodeScanner
                open={isScanning}
                onOpenChange={setIsScanning}
                onScanSuccess={(code) => fetchProductDetails(code)}
            />
        </Dialog >
    )
}

function FormCombobox({ items, value, onChange, placeholder, allowCustom = false }: {
    items: string[]
    value: string
    onChange: (val: string) => void
    placeholder: string
    allowCustom?: boolean
}) {
    const [open, setOpen] = useState(false)
    const [search, setSearch] = useState("")

    // Filter items based on search
    const filteredItems = search
        ? items.filter(item => item.toLowerCase().includes(search.toLowerCase()))
        : items

    // If value is custom (not in items), add it to top
    const displayItems = value && !items.includes(value)
        ? [value, ...filteredItems]
        : filteredItems

    const handleSelect = (item: string) => {
        onChange(item)
        setOpen(false)
        setSearch("")
    }

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
                <Button
                    type="button"
                    variant="outline"
                    role="combobox"
                    aria-expanded={open}
                    className="w-full justify-between font-normal"
                >
                    {value
                        ? value
                        : <span className="text-muted-foreground">{placeholder}</span>}
                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
            </PopoverTrigger>
            <PopoverContent className="w-[--radix-popover-trigger-width] p-0" align="start">
                <div className="flex flex-col">
                    {/* Search Input */}
                    <div className="flex items-center border-b px-3">
                        <input
                            className="flex h-10 w-full bg-transparent py-3 text-sm outline-none placeholder:text-muted-foreground"
                            placeholder={`Search ${placeholder.toLowerCase()}...`}
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                        />
                    </div>

                    {/* Items List */}
                    <div className="max-h-[200px] overflow-auto p-1">
                        {displayItems.length === 0 && !allowCustom && (
                            <div className="py-6 text-center text-sm text-muted-foreground">
                                No results found.
                            </div>
                        )}

                        {displayItems.length === 0 && allowCustom && search && (
                            <div className="p-2">
                                <p className="text-xs text-muted-foreground mb-2">No results found.</p>
                                <Button
                                    type="button"
                                    variant="secondary"
                                    size="sm"
                                    className="w-full"
                                    onClick={() => handleSelect(search)}
                                >
                                    + Add "{search}"
                                </Button>
                            </div>
                        )}

                        {displayItems.map((item) => (
                            <div
                                key={item}
                                className={cn(
                                    "relative flex cursor-pointer select-none items-center rounded-sm px-2 py-1.5 text-sm outline-none hover:bg-accent hover:text-accent-foreground",
                                    value === item && "bg-accent"
                                )}
                                onClick={() => handleSelect(item)}
                            >
                                <Check
                                    className={cn(
                                        "mr-2 h-4 w-4",
                                        value === item ? "opacity-100" : "opacity-0"
                                    )}
                                />
                                {item}
                            </div>
                        ))}
                    </div>
                </div>
            </PopoverContent>
        </Popover>
    )
}

'use client'

import { useState, useTransition, useEffect } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import * as z from 'zod'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from '@/components/ui/dialog'
import {
    Form,
    FormControl,
    FormField,
    FormItem,
    FormLabel,
    FormMessage,
} from '@/components/ui/form'
import { Input } from '@/components/ui/input'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Item } from '@/types'
import { recordStockMovement } from '@/app/actions/stock'
import { Loader2 } from 'lucide-react'

const formSchema = z.object({
    quantity: z.coerce.number().min(0.01, 'Quantity must be positive'),
    type: z.enum(['IN', 'OUT']),
    reason: z.string().optional(),
})

type FormValues = z.infer<typeof formSchema>

interface QuickStockDialogProps {
    item: Item
    open: boolean
    onOpenChange: (open: boolean) => void
    defaultType?: 'IN' | 'OUT'
}

export function QuickStockDialog({ item, open, onOpenChange, defaultType = 'IN' }: QuickStockDialogProps) {
    const [isPending, startTransition] = useTransition()

    const form = useForm<unknown>({
        resolver: zodResolver(formSchema),
        defaultValues: {
            quantity: 0,
            type: defaultType,
            reason: '',
        },
    })

    // Reset form when dialog opens or defaultType changes
    useEffect(() => {
        if (open) {
            form.reset({
                quantity: 0,
                type: defaultType,
                reason: '',
            })
        }
    }, [open, defaultType, form])

    async function onSubmit(values: FormValues) {
        const formData = new FormData()
        formData.append('item_id', item.id)
        formData.append('quantity', values.quantity.toString())
        formData.append('type', values.type)
        if (values.reason) formData.append('reason', values.reason)

        startTransition(async () => {
            const result = await recordStockMovement({}, formData)

            if (result.error) {
                toast.error(result.error)
            } else {
                toast.success(result.message)
                onOpenChange(false)
            }
        })
    }

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="sm:max-w-[425px]">
                <DialogHeader>
                    <DialogTitle>Quick Stock Update</DialogTitle>
                    <DialogDescription>
                        Adjust stock for {item.name}. Current: {item.current_stock} {item.unit}
                    </DialogDescription>
                </DialogHeader>
                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                            <FormField
                                control={form.control}
                                name="quantity"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Quantity</FormLabel>
                                        <FormControl>
                                            <Input type="number" step="0.01" {...field} />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                            <FormField
                                control={form.control}
                                name="type"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel>Type</FormLabel>
                                        <Select onValueChange={field.onChange} defaultValue={field.value} value={field.value}>
                                            <FormControl>
                                                <SelectTrigger>
                                                    <SelectValue />
                                                </SelectTrigger>
                                            </FormControl>
                                            <SelectContent>
                                                <SelectItem value="IN">IN (Add)</SelectItem>
                                                <SelectItem value="OUT">OUT (Remove)</SelectItem>
                                            </SelectContent>
                                        </Select>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                        </div>
                        <FormField
                            control={form.control}
                            name="reason"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel>Reason (Optional)</FormLabel>
                                    <FormControl>
                                        <Input placeholder="e.g., Sale, Damage, Adjustment" {...field} />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                        <DialogFooter>
                            <Button type="submit" disabled={isPending}>
                                {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                Update Stock
                            </Button>
                        </DialogFooter>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>
    )
}

